<?php
require_once '../config.php';requireAdmin();verifyCsrf();
if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='delete'){$s=$pdo->prepare("UPDATE products SET active=0 WHERE id=?");$s->execute([(int)$_POST['id']]);}redirect('products.php');}
$products=$pdo->query("SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC")->fetchAll();$pageTitle='Produtos';include '../includes/header.php';?>
<div class="page-head"><div class="container"><div class="section-kicker">GESTÃO DO CATÁLOGO</div><h1>PRODUTOS</h1></div></div><section class="section"><div class="container"><div class="d-flex justify-content-between mb-4"><h2 class="admin-title">TODOS OS PRODUTOS</h2><a class="btn-red" href="product-form.php">+ NOVO PRODUTO</a></div><div class="table-responsive"><table class="table table-dark align-middle"><thead><tr><th>Nome</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['category']) ?></td><td><?= money($p['price']) ?></td><td><?= $p['stock'] ?></td><td><?= $p['active']?'Ativo':'Inativo' ?></td><td><a class="text-info me-3" href="product-form.php?id=<?= $p['id'] ?>">Editar</a><?php if($p['active']): ?><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Desativar este produto?">Desativar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><a class="btn-outline" href="index.php">VOLTAR AO PAINEL</a></div></section><?php include '../includes/footer.php'; ?>
